colors_and_type.css.text:
/*
 * maude-v2 — design tokens · "Light glass with a spark"
 *
 * Authoritative token file for the Maude v2.0.0 redesign (designer-first, light,
 * floating chrome over a full-window canvas). Every canvas built with --ds=maude-v2
 * and every preview/<slug>.tsx specimen links to this file through _layout.css.
 *
 * Locked direction (Stage-3 moodboard, ui/v2/maude-v2-moodboard.tsx → artboard
 * "direction-mix"): Mac-native frosted islands (macOS Liquid Glass × Craft × Framer)
 * plus a touch of the playful workshop (FigJam × Kinopio): colour lives ON the
 * canvas, the dock is rounder, and a warm spark is reserved for AI moments only.
 *
 * Roles — one token, one job:
 *   --accent*   azure — primary action, current selection, focus. Functional only.
 *   --spark*    vermilion — the AI (agent cursor, "Ask AI" send, AI-made badges). Never decoration, never error.
 *   --object-*  the canvas object palette (stickies, shapes, canvas colour chips). Lives on the canvas, not in chrome.
 *   --island-*  the frosted floating-chrome material (panels, dock, menus).
 *
 * Themes: light is the default (it follows macOS appearance in the app); dark is an
 * equal-status counterpart. Every family token is declared in BOTH blocks.
 * No contrast ratios are asserted in this file — pairs are verified by the a11y pass.
 */

:root,
.maude-v2[data-theme="light"],
.ds[data-theme="light"] {
  color-scheme: light;

  /* ─── Surfaces (deepest → highest) ─────────────────────────────────── */
  --bg-0: oklch(0.978 0.005 240);   /* the canvas / page                     */
  --bg-1: oklch(0.995 0.002 240);   /* island / panel body                   */
  --bg-2: oklch(1 0 0);             /* popover, menu, sheet                  */
  --bg-3: oklch(0.958 0.006 240);   /* input well, row hover                 */
  --bg-4: oklch(0.928 0.008 240);   /* pressed, selected-row-without-accent  */

  /* ─── Borders (alpha of ink, so they sit on any surface) ───────────── */
  --border-subtle:  oklch(0.24 0.014 250 / 0.07);
  --border-default: oklch(0.24 0.014 250 / 0.12);
  --border-strong:  oklch(0.24 0.014 250 / 0.24);

  /* ─── Text ─────────────────────────────────────────────────────────── */
  --fg-0: oklch(0.24 0.014 250);    /* primary          */
  --fg-1: oklch(0.42 0.012 250);    /* secondary        */
  --fg-2: oklch(0.505 0.010 250);   /* tertiary / meta — holds on --bg-3/--bg-4 */
  --fg-3: oklch(0.70 0.008 250);    /* disabled         */

  /* ─── Accent — single azure, functional only ──────────────────────── */
  --accent:        oklch(0.53 0.175 238);           /* white text on it ≈ 4.9:1 (computed) */
  --accent-hover:  oklch(0.49 0.170 238);
  --accent-active: oklch(0.46 0.165 238);
  --accent-fg:     oklch(1 0 0);
  --focus-ring:    var(--accent);                   /* keyboard focus outline */
  --accent-text:   oklch(0.47 0.170 238);           /* azure used AS TEXT on light surfaces — ≥4.7:1 even on --accent-muted over bg-3 */
  --accent-soft:  oklch(0.53 0.175 238 / 0.12);
  --accent-muted: var(--accent-soft);   /* selected row, chip bg   */
  --selection:   oklch(0.53 0.175 238 / 0.22);
  --accent-tint: var(--selection);   /* text selection, rings   */

  /* ─── Spark — the AI's colour (reserved role, not a second accent) ─── */
  --x-spark:        oklch(0.66 0.200 36);
  --spark: var(--x-spark);
  --x-spark-hover:  oklch(0.70 0.190 38);
  --spark-hover: var(--x-spark-hover);
  --x-spark-fg:     oklch(0.20 0.030 36);
  --spark-fg: var(--x-spark-fg);            /* dark ink on the spark — keeps it bright and far from error red */
  --x-spark-text:   oklch(0.50 0.170 36);
  --spark-text: var(--x-spark-text);            /* spark used AS TEXT on light surfaces */
  --x-spark-muted:  oklch(0.66 0.200 36 / 0.12);
  --spark-muted: var(--x-spark-muted);

  /* ─── Status ───────────────────────────────────────────────────────── */
  --status-success: oklch(0.60 0.140 152);
  --status-warn:    oklch(0.72 0.150 78);
  --status-error:   oklch(0.55 0.190 22);
  --status-info:    oklch(0.60 0.140 250);
  --status-success-text: oklch(0.52 0.130 152);    /* status colours used AS TEXT */
  --status-warn-text:    oklch(0.54 0.120 70);
  --status-error-text:   oklch(0.52 0.190 22);
  --status-info-text:    oklch(0.535 0.130 250);

  /* ─── Controls ─────────────────────────────────────────────────────── */
  --x-control-off: oklch(0.64 0.010 250);
  --control-off: var(--x-control-off);            /* switch track / unchecked box edge */

  /* ─── Presence (people + the agent) ────────────────────────────────── */
  --presence-online:  oklch(0.66 0.150 152);
  --presence-away:    oklch(0.76 0.140 80);
  --presence-offline: oklch(0.72 0.008 250);
  --x-presence-agent:   var(--spark);
  --presence-agent: var(--x-presence-agent);

  /* ─── Canvas object palette — colour lives on the canvas ───────────── */
  --palette-1: oklch(0.91 0.120 95);
  --object-yellow: var(--palette-1);
  --palette-2:  oklch(0.82 0.120 152);
  --object-green: var(--palette-2);
  --palette-3:  oklch(0.83 0.075 300);
  --object-lilac: var(--palette-3);
  --palette-4:  oklch(0.83 0.095 32);
  --object-coral: var(--palette-4);
  --palette-5:    oklch(0.85 0.070 230);
  --object-sky: var(--palette-5);
  --palette-6:   oklch(0.90 0.006 250);
  --object-grey: var(--palette-6);
  --palette-ink:    oklch(0.24 0.014 250);
  --object-ink: var(--palette-ink);           /* text on any sticky */

  /* ─── Canvas ───────────────────────────────────────────────────────── */
  --x-canvas-bg:   var(--bg-0);
  --canvas-bg: var(--x-canvas-bg);
  --x-canvas-dot:  oklch(0.80 0.010 240);
  --canvas-dot: var(--x-canvas-dot);
  --x-canvas-grid: 20px;
  --canvas-grid: var(--x-canvas-grid);

  /* ─── Island — the floating-chrome material (signature) ───────────── */
  --x-island-bg:     oklch(0.995 0.002 240 / 0.88);
  --island-bg: var(--x-island-bg);   /* ~88% opaque: frost, never peek-through */
  --x-island-bg-strong: oklch(0.995 0.002 240 / 0.96);
  --island-bg-strong: var(--x-island-bg-strong); /* large islands over busy canvas: inspector, AI chat panel */
  --x-island-blur:   16px;
  --island-blur: var(--x-island-blur);
  --x-island-edge:   oklch(0.24 0.014 250 / 0.10);
  --island-edge: var(--x-island-edge);    /* 0.5px inner hairline   */
  --x-island-shadow: 0 2px 10px oklch(0.24 0.030 250 / 0.07), 0 0.5px 1.5px oklch(0.24 0.030 250 / 0.06);
  --island-shadow: var(--x-island-shadow);

  /* ─── Shadows / elevation (soft) ───────────────────────────────────── */
  --shadow-sm: 0 1px 2px oklch(0.24 0.030 250 / 0.08);
  --shadow-md: 0 3px 10px oklch(0.24 0.030 250 / 0.08), 0 1px 2px oklch(0.24 0.030 250 / 0.05);
  --shadow-lg: 0 8px 24px oklch(0.24 0.030 250 / 0.11), 0 2px 4px oklch(0.24 0.030 250 / 0.06);

  /* ─── Schema v1 roles (V2-2.15 bring-up) ─── */
  --accent-on-soft: var(--accent-text); /* azure as text on the soft tint */
  --scrim: color-mix(in oklch, var(--fg-0) 40%, transparent); /* modal backdrop */
  --status-success-fg: var(--accent-fg); /* text on the fill */
  --status-warn-fg: var(--fg-0); /* text on the fill */
  --status-error-fg: var(--accent-fg); /* text on the fill */
  --status-info-fg: var(--accent-fg); /* text on the fill */
  --status-success-soft: color-mix(in oklch, var(--status-success) 12%, transparent); /* tint, same alpha as --accent-soft */
  --status-warn-soft: color-mix(in oklch, var(--status-warn) 12%, transparent); /* tint, same alpha as --accent-soft */
  --status-error-soft: color-mix(in oklch, var(--status-error) 12%, transparent); /* tint, same alpha as --accent-soft */
  --status-info-soft: color-mix(in oklch, var(--status-info) 12%, transparent); /* tint, same alpha as --accent-soft */
}

.maude-v2[data-theme="dark"],
.ds[data-theme="dark"] {
  color-scheme: dark;

  /* ─── Surfaces ─────────────────────────────────────────────────────── */
  --bg-0: oklch(0.205 0.006 250);
  --bg-1: oklch(0.245 0.007 250);
  --bg-2: oklch(0.275 0.008 250);
  --bg-3: oklch(0.300 0.008 250);
  --bg-4: oklch(0.340 0.009 250);

  /* ─── Borders ──────────────────────────────────────────────────────── */
  --border-subtle:  oklch(1 0 0 / 0.06);
  --border-default: oklch(1 0 0 / 0.11);
  --border-strong:  oklch(1 0 0 / 0.20);

  /* ─── Text ─────────────────────────────────────────────────────────── */
  --fg-0: oklch(0.965 0.004 250);
  --fg-1: oklch(0.800 0.006 250);
  --fg-2: oklch(0.720 0.008 250);
  --fg-3: oklch(0.500 0.008 250);

  /* ─── Accent ───────────────────────────────────────────────────────── */
  --accent:        oklch(0.54 0.165 238);           /* white text on it ≈ 4.7:1 (computed) */
  --accent-hover:  oklch(0.50 0.160 238);
  --accent-active: oklch(0.47 0.155 238);
  --accent-fg:     oklch(1 0 0);
  --focus-ring:    oklch(0.72 0.140 238);           /* dark accent is too deep for a 3:1 outline on bg-3/bg-4 — computed 5.6 / 4.8 */
  --accent-text:   oklch(0.72 0.140 238);           /* azure used AS TEXT on dark surfaces */
  --accent-soft:  oklch(0.64 0.165 238 / 0.18);
  --accent-muted: var(--accent-soft);
  --selection:   oklch(0.64 0.165 238 / 0.30);
  --accent-tint: var(--selection);

  /* ─── Spark ────────────────────────────────────────────────────────── */
  --x-spark:        oklch(0.70 0.185 38);
  --spark: var(--x-spark);
  --x-spark-hover:  oklch(0.74 0.180 38);
  --spark-hover: var(--x-spark-hover);
  --x-spark-fg:     oklch(0.20 0.030 38);
  --spark-fg: var(--x-spark-fg);
  --x-spark-text:   oklch(0.74 0.150 38);
  --spark-text: var(--x-spark-text);
  --x-spark-muted:  oklch(0.70 0.185 38 / 0.18);
  --spark-muted: var(--x-spark-muted);

  /* ─── Status ───────────────────────────────────────────────────────── */
  --status-success: oklch(0.72 0.140 152);
  --status-warn:    oklch(0.80 0.140 80);
  --status-error:   oklch(0.69 0.170 22);
  --status-info:    oklch(0.70 0.130 250);
  --status-success-text: oklch(0.72 0.140 152);
  --status-warn-text:    oklch(0.80 0.140 80);
  --status-error-text:   oklch(0.69 0.170 22);
  --status-info-text:    oklch(0.70 0.130 250);

  /* ─── Controls ─────────────────────────────────────────────────────── */
  --x-control-off: oklch(0.55 0.008 250);
  --control-off: var(--x-control-off);

  /* ─── Presence ─────────────────────────────────────────────────────── */
  --presence-online:  oklch(0.72 0.150 152);
  --presence-away:    oklch(0.80 0.140 80);
  --presence-offline: oklch(0.52 0.008 250);
  --x-presence-agent:   var(--spark);
  --presence-agent: var(--x-presence-agent);

  /* ─── Canvas object palette (deeper, so stickies don't glow on dark) ─ */
  --palette-1: oklch(0.80 0.120 95);
  --object-yellow: var(--palette-1);
  --palette-2:  oklch(0.72 0.110 152);
  --object-green: var(--palette-2);
  --palette-3:  oklch(0.72 0.080 300);
  --object-lilac: var(--palette-3);
  --palette-4:  oklch(0.72 0.100 32);
  --object-coral: var(--palette-4);
  --palette-5:    oklch(0.74 0.080 230);
  --object-sky: var(--palette-5);
  --palette-6:   oklch(0.62 0.008 250);
  --object-grey: var(--palette-6);
  --palette-ink:    oklch(0.22 0.014 250);
  --object-ink: var(--palette-ink);

  /* ─── Canvas ───────────────────────────────────────────────────────── */
  --x-canvas-bg:   var(--bg-0);
  --canvas-bg: var(--x-canvas-bg);
  --x-canvas-dot:  oklch(0.36 0.008 250);
  --canvas-dot: var(--x-canvas-dot);
  --x-canvas-grid: 20px;
  --canvas-grid: var(--x-canvas-grid);

  /* ─── Island ───────────────────────────────────────────────────────── */
  --x-island-bg:     oklch(0.245 0.007 250 / 0.88);
  --island-bg: var(--x-island-bg);
  --x-island-bg-strong: oklch(0.245 0.007 250 / 0.96);
  --island-bg-strong: var(--x-island-bg-strong);
  --x-island-blur:   16px;
  --island-blur: var(--x-island-blur);
  --x-island-edge:   oklch(1 0 0 / 0.09);
  --island-edge: var(--x-island-edge);
  --x-island-shadow: 0 4px 14px oklch(0 0 0 / 0.30), 0 0.5px 1.5px oklch(0 0 0 / 0.26);
  --island-shadow: var(--x-island-shadow);

  /* ─── Shadows ──────────────────────────────────────────────────────── */
  --shadow-sm: 0 1px 2px oklch(0 0 0 / 0.30);
  --shadow-md: 0 3px 10px oklch(0 0 0 / 0.30), 0 1px 2px oklch(0 0 0 / 0.22);
  --shadow-lg: 0 10px 28px oklch(0 0 0 / 0.38), 0 2px 4px oklch(0 0 0 / 0.26);

  /* ─── Schema v1 roles (V2-2.15 bring-up) ─── */
  --accent-on-soft: var(--accent-text); /* azure as text on the soft tint */
  --scrim: color-mix(in oklch, var(--bg-0) 60%, transparent); /* modal backdrop */
  --status-success-fg: var(--bg-0); /* text on the fill */
  --status-warn-fg: var(--bg-0); /* text on the fill */
  --status-error-fg: var(--bg-0); /* text on the fill */
  --status-info-fg: var(--bg-0); /* text on the fill */
  --status-success-soft: color-mix(in oklch, var(--status-success) 18%, transparent); /* tint, same alpha as --accent-soft */
  --status-warn-soft: color-mix(in oklch, var(--status-warn) 18%, transparent); /* tint, same alpha as --accent-soft */
  --status-error-soft: color-mix(in oklch, var(--status-error) 18%, transparent); /* tint, same alpha as --accent-soft */
  --status-info-soft: color-mix(in oklch, var(--status-info) 18%, transparent); /* tint, same alpha as --accent-soft */
}

/* Theme-independent tokens (same in both themes). */
:root,
.maude-v2[data-theme="light"],
.ds[data-theme="light"],
.maude-v2[data-theme="dark"],
.ds[data-theme="dark"] {
  /* ─── Radii — soft, concentric (island 14 › control 10 › chip 6) ───── */
  --radius-xs:   4px;
  --radius-sm:   6px;
  --radius-md:   10px;
  --radius-lg:   14px;
  --radius-xl:   20px;    /* the dock, sheets */
  --radius-pill: 999px;

  /* ─── Spacing — 8px rhythm with a 4px half-step ────────────────────── */
  --space-0: 0;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;

  /* ─── Typography — native macOS faces; mono only in Advanced ──────── */
  /* system-ui first: on macOS it IS SF Pro (Text/Display picked by optical size) whether or not
     Apple's SF Pro download is installed, so every Mac renders the same. Named fallbacks follow for
     other platforms. Rounded is WebKit-only (ui-rounded) — elsewhere it falls back to the body face. */
  --font-display: system-ui, -apple-system, "Segoe UI Variable Display", "Segoe UI", Roboto, "Inter", sans-serif;
  --font-body:    system-ui, -apple-system, "Segoe UI Variable Text", "Segoe UI", Roboto, "Inter", sans-serif;
  --font-rounded: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, sans-serif;   /* playful surfaces: Home, empty states, stickies */
  --font-mono:    ui-monospace, "SF Mono", Menlo, "Cascadia Mono", Consolas, "Liberation Mono", "DejaVu Sans Mono", monospace;  /* Advanced + code only */

  /* Weights — capped at semibold. Bold (700) is not part of this DS. */
  --weight-regular:  400;
  --w-regular: var(--weight-regular);
  --weight-medium:   500;
  --w-medium: var(--weight-medium);
  --weight-semibold: 600;
  --w-semibold: var(--weight-semibold);

  /* Type scale — ratio 1.2 from a 14px base; xs/sm held at legible UI floors. */
  --type-xs:   11px;  --lh-xs:   1.36;
  --type-sm:   12px;  --lh-sm:   1.42;
  --type-base: 14px;  --lh-base: 1.45;
  --type-md:   17px;  --lh-md:   1.40;
  --type-lg:   20px;  --lh-lg:   1.30;
  --type-xl:   24px;  --lh-xl:   1.22;
  --type-2xl:  29px;  --lh-2xl:  1.14;
  --type-3xl:  35px;  --lh-3xl:  1.08;

  --tracking-tight: -0.015em;
  --tracking-wide:  0.02em;

  /* ─── Motion — gentle, with a drop of spring for playful moments ──── */
  --dur-flip:   120ms;   /* hover, press, toggle                        */
  --dur-soft:   160ms;   /* fades, tooltips                             */
  --dur-panel:  220ms;   /* island collapse ↔ icon, menu open           */
  --dur-route:  280ms;   /* canvas switch, project tab                  */
  --dur-signature-1: 420ms;
  --dur-spring: var(--dur-signature-1);   /* playful only: AI done, new sticky lands     */
  --ease-out:    cubic-bezier(0.25, 0.8, 0.25, 1);
  --ease-in-out: cubic-bezier(0.45, 0, 0.2, 1);
  --ease-signature-1: linear(0, 0.24 8%, 0.62 19%, 0.93 32%, 1.045 45%, 1.03 57%, 0.997 74%, 1);
  --ease-spring: var(--ease-signature-1);

  /* ─── Guides — smart guides, spacing chips, padding bands (canvas 14 › ed-*) ─
   * One fixed magenta in both themes: not derived from the spark (AI) and distinct
   * from the selection azure (238) and the AI vermilion (36). White chip text on it
   * ≈ 5.4:1 in both themes (14 Editing header; verified by the a11y pass). Bands mix
   * it in oklch at 24 % (40 % hot) — 14 Editing.css .ed-band; that ratio lives in the
   * component, not here. */
  --x-guide:      oklch(0.55 0.20 328);
  --guide: var(--x-guide);
  --x-guide-fg:   oklch(1 0 0);
  --guide-fg: var(--x-guide-fg);

  /* ─── Layout — the canvas is the whole window ─────────────────────── */
  --layout-max-w:  none;
  --layout-gutter: var(--space-5);

  /* ─── Schema v1 roles (V2-2.15 bring-up) ─── */
  --focus-ring-width: 2px; /* _components.css focus outlines are 2px */
  --focus-ring-offset: 2px; /* _components.css .btn/.switch offset */
  --weight-bold: var(--weight-semibold); /* bold is not part of this DS — capped at semibold */
  --tracking-normal: 0;
}

@media (prefers-reduced-motion: reduce) {
  :root,
  .maude-v2[data-theme="light"],
  .ds[data-theme="light"],
  .maude-v2[data-theme="dark"],
  .ds[data-theme="dark"] {
    --dur-flip:   1ms;
    --dur-soft:   1ms;
    --dur-panel:  1ms;
    --dur-route:  1ms;
    --dur-signature-1: 1ms;
    --dur-spring: var(--dur-signature-1);
  }
}

preview/_components.css.text:
/*
 * maude-v2 — shared component anatomy
 *
 * Pulled in by _layout.css, so every specimen (and every canvas that imports
 * _layout.css) gets these classes. Specimens keep only demo-specific CSS inline.
 *
 * Material rule: chrome = .island (frosted, ~88% opaque, soft concentric radius,
 * 0.5px inner edge). Controls inside an island are one radius step smaller
 * (island 14 › control 10 › chip 6) so corners nest.
 *
 * Colour rule: --accent = action/selection/focus · --spark = AI only ·
 * --object-* = things ON the canvas (stickies, shapes), never chrome fills.
 */

/* ─── Island — the floating-chrome material ──────────────────────────────── */
.island {
  background: var(--island-bg);
  backdrop-filter: blur(var(--island-blur)) saturate(1.4);
  -webkit-backdrop-filter: blur(var(--island-blur)) saturate(1.4);
  border-radius: var(--radius-lg);
  box-shadow: var(--island-shadow), inset 0 0 0 0.5px var(--island-edge);
  color: var(--fg-0);
}
.island--pad { padding: var(--space-3); }
.island-title {
  font-size: var(--type-xs);
  font-weight: var(--w-semibold);
  color: var(--fg-2);
  margin: 0 0 var(--space-2);
  padding: 0 var(--space-1);
}

/* The dock — rounder and a little chunkier than the other islands. */
.dock {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-2);
  border-radius: var(--radius-xl);
}
.dock .divider-v { width: 1px; height: 24px; background: var(--border-default); margin: 0 var(--space-1); }

/* ─── Buttons ────────────────────────────────────────────────────────────── */
.btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  height: 32px;
  padding: 0 var(--space-3);
  border: 0;
  border-radius: var(--radius-md);
  font: inherit;
  font-size: var(--type-sm);
  font-weight: var(--w-semibold);
  line-height: 1;
  cursor: pointer;
  background: var(--bg-3);
  color: var(--fg-0);
  transition: background var(--dur-flip) var(--ease-out), transform var(--dur-flip) var(--ease-out), box-shadow var(--dur-flip) var(--ease-out);
}
.btn:hover { background: var(--bg-4); }
.btn:active { transform: scale(0.97); }
.btn:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.btn[disabled] { color: var(--fg-3); cursor: not-allowed; transform: none; }

.btn--primary { background: var(--accent); color: var(--accent-fg); }
.btn--primary:hover { background: var(--accent-hover); }
.btn--primary:active { background: var(--accent-active); }

.btn--ghost { background: transparent; color: var(--fg-1); }
.btn--ghost:hover { background: var(--bg-3); color: var(--fg-0); }

.btn--spark { background: var(--accent); color: var(--accent-fg); }
.btn--spark:hover { background: var(--accent-hover); }
/* An AI action is still an action: azure fill ("Azure acts"), the spark only as its glyph, in the button's own colour.
   Vermilion fills stay for AI presence (cursor, working tag) — never a button you are asked to press. */
.btn--spark svg path, .ask .send svg path { fill: currentColor; }

.btn--lg { height: 40px; padding: 0 var(--space-4); font-size: var(--type-base); border-radius: var(--radius-lg); }
.btn--sm { height: 26px; padding: 0 var(--space-2); font-size: var(--type-xs); border-radius: var(--radius-sm); }

/* Square icon button — the unit of every island and the dock. */
.icon-btn {
  appearance: none;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--fg-0);
  cursor: pointer;
  transition: background var(--dur-flip) var(--ease-out);
}
.icon-btn:hover { background: var(--bg-3); }
.icon-btn[aria-pressed="true"] { background: var(--accent-muted); color: var(--accent-text); }  /* the active tool is muted — Share stays the one solid azure */
.icon-btn:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 1px; }
.icon-btn svg { width: 16px; height: 16px; display: block; }
.dock .icon-btn { width: 40px; height: 40px; border-radius: calc(var(--radius-xl) - var(--space-2)); }
.dock .icon-btn svg { width: 18px; height: 18px; }

/* ─── Inputs ─────────────────────────────────────────────────────────────── */
.input, .select, .textarea {
  appearance: none;
  width: 100%;
  font: inherit;
  font-size: var(--type-sm);
  color: var(--fg-0);
  background: var(--bg-3);
  border: 0;
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-3);
  box-shadow: inset 0 0 0 0.5px var(--border-subtle);
  transition: box-shadow var(--dur-flip) var(--ease-out), background var(--dur-flip) var(--ease-out);
}
.input { height: 32px; }
.textarea { min-height: 72px; resize: vertical; line-height: var(--lh-sm); }
.input::placeholder, .textarea::placeholder { color: var(--fg-2); }
.input:focus, .select:focus, .textarea:focus {
  outline: none;
  background: var(--bg-2);
  box-shadow: 0 0 0 3px var(--accent-tint), inset 0 0 0 1px var(--focus-ring);
}
.field { display: flex; flex-direction: column; gap: var(--space-1); }
.field-label { font-size: var(--type-xs); font-weight: var(--w-semibold); color: var(--fg-1); }
.field-hint { font-size: var(--type-xs); color: var(--fg-2); }

/* The AI prompt — the one input that carries the spark. */
.ask {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-1) var(--space-1) var(--space-3);
  border-radius: var(--radius-lg);
  background: var(--bg-2);
  box-shadow: inset 0 0 0 0.5px var(--border-default);
}
.ask input { flex: 1; border: 0; background: transparent; font: inherit; font-size: var(--type-sm); color: var(--fg-0); outline: none; min-width: 0; }
.ask input::placeholder { color: var(--fg-2); }
.ask .send {
  display: grid; place-items: center;
  width: 28px; height: 28px;
  border-radius: var(--radius-md);
  background: var(--accent);
  color: var(--accent-fg);
}

/* ─── Segmented control + switch ─────────────────────────────────────────── */
.seg { display: inline-flex; gap: 2px; padding: 2px; border-radius: var(--radius-md); background: var(--bg-3); }
.seg button {
  appearance: none; border: 0; background: transparent; font: inherit; font-size: var(--type-sm);
  color: var(--fg-1); padding: var(--space-1) var(--space-3); border-radius: calc(var(--radius-md) - 2px); cursor: pointer;
  transition: background var(--dur-flip) var(--ease-out), color var(--dur-flip) var(--ease-out);
}
.seg button[aria-pressed="true"] { background: var(--bg-2); color: var(--fg-0); box-shadow: var(--shadow-sm), inset 0 0 0 1px var(--accent); }

.switch {
  appearance: none; position: relative; width: 34px; height: 20px; border-radius: var(--radius-pill);
  background: var(--control-off); border: 0; cursor: pointer; transition: background var(--dur-flip) var(--ease-out);
}
.switch::after {
  content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%;
  background: var(--bg-2); box-shadow: var(--shadow-sm); transition: transform var(--dur-flip) var(--ease-out);
}
.switch[aria-checked="true"] { background: var(--accent); }
.switch[aria-checked="true"]::after { transform: translateX(14px); }
.switch:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }

/* ─── Chips, badges, keys ────────────────────────────────────────────────── */
.chip {
  display: inline-flex; align-items: center; gap: var(--space-1);
  height: 22px; padding: 0 var(--space-2); border-radius: var(--radius-sm);
  font-size: var(--type-xs); font-weight: var(--w-medium); color: var(--fg-1); background: var(--bg-3);
}
.chip--accent { color: var(--accent-text); background: var(--accent-muted); }
.chip--spark { color: var(--spark-text); background: var(--spark-muted); }
.kbd {
  display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 var(--space-1);
  border-radius: var(--radius-xs); font-size: var(--type-xs); font-family: var(--font-body);
  color: var(--fg-1); background: var(--bg-2); box-shadow: inset 0 -1px 0 var(--border-default), inset 0 0 0 0.5px var(--border-default);
}

/* ─── Rows (lists inside islands) ────────────────────────────────────────── */
.row-item {
  display: flex; align-items: center; gap: var(--space-2);
  padding: var(--space-1) var(--space-2); min-height: 30px;
  border-radius: var(--radius-sm); font-size: var(--type-sm); color: var(--fg-0);
}
.row-item:hover { background: var(--bg-3); }
.row-item[aria-current="true"] { background: var(--accent-muted); font-weight: var(--w-semibold); }
.row-item .thumb { width: 22px; height: 16px; border-radius: var(--radius-xs); box-shadow: inset 0 0 0 0.5px var(--border-default); flex: none; }

/* ─── Canvas objects — colour lives here ─────────────────────────────────── */
.sticky {
  width: 120px; min-height: 104px; padding: var(--space-3);
  border-radius: var(--radius-xs);
  font-family: var(--font-rounded); font-weight: var(--w-semibold); font-size: var(--type-base); line-height: var(--lh-sm);
  color: var(--object-ink);
  box-shadow: 0 6px 12px oklch(0 0 0 / 0.12);
}
.sticky--yellow { background: var(--object-yellow); }
.sticky--green  { background: var(--object-green); }
.sticky--lilac  { background: var(--object-lilac); }
.sticky--coral  { background: var(--object-coral); }
.sticky--sky    { background: var(--object-sky); }

/* ─── Collapse-to-icon (signature motion) ────────────────────────────────── */
.collapsible {
  transform-origin: top right;
  transition: transform var(--dur-panel) var(--ease-out), opacity var(--dur-panel) var(--ease-out);
}
.collapsible[data-collapsed="true"] { transform: scale(0.18); opacity: 0; pointer-events: none; }

/* ─── Motion role classes — zero-JS escape hatch (DDR-049) ───────────────── */
/* Justified zero-JS case (bypass-log): an ambient "AI is here" breath on presence tags inside
   static specimens/canvases. Slow (1.6 s a leg) with a 0.6 opacity floor — a cue, never a strobe. */
/* The element itself stays at full strength (a pale tag reads as disabled); only a soft
   spark halo breathes around it. */
@keyframes mv2-soft { from { box-shadow: 0 0 0 0 var(--spark-muted); } to { box-shadow: 0 0 0 5px var(--spark-muted); } }
.motion-soft { animation: mv2-soft 1.6s var(--ease-in-out) infinite alternate; }

/* ─── Focus + disabled states shared by every island control ─────────────── */
.seg button:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 1px; }
.ask:focus-within { box-shadow: 0 0 0 3px var(--accent-tint), inset 0 0 0 1px var(--focus-ring); }
.row-item:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: -2px; }
.btn--primary[disabled], .btn--spark[disabled] { background: var(--bg-3); color: var(--fg-3); }

/* Loops stop entirely when the user asks for less motion (a 1ms infinite loop would strobe). */
@media (prefers-reduced-motion: reduce) {
  .motion-soft { animation: none; }
}
[data-reduced-motion="true"] .motion-soft { animation: none; }

/* ─── Schema v1 class contract (V2-2.15 bring-up) ─────────────────────────────
 * The core components this system had only as specimen classes, lifted verbatim from those
 * specimens (source in each comment) under the schema's class names. Scoped to `.ds` (the
 * <DSRoot> wrapper), so a canvas that names a local class `.card` or `.badge` under the
 * `.maude-v2` wrapper renders exactly as before. components.json maps every core component;
 * a component this system has no rule for is a declared gap there (null), never invented. */

/* Checkbox ← components-toggles.css .tg-check / .tg-radio */
:where(.ds) .checkbox, :where(.ds) .radio {
  appearance: none; flex: none; margin: 0; width: 16px; height: 16px; display: inline-grid; place-items: center; cursor: pointer;
  background: var(--bg-2); box-shadow: inset 0 0 0 1px var(--control-off);
  transition: background var(--dur-flip) var(--ease-out), box-shadow var(--dur-flip) var(--ease-out);
}
:where(.ds) .checkbox { border-radius: var(--radius-xs); }
:where(.ds) .radio { border-radius: var(--radius-pill); }
:where(.ds) .checkbox::after {
  content: ""; width: 8px; height: 4px; margin-top: -2px;
  border-left: 2px solid var(--accent-fg); border-bottom: 2px solid var(--accent-fg);
  transform: rotate(-45deg) scale(0.4); opacity: 0;
  transition: transform var(--dur-flip) var(--ease-out), opacity var(--dur-flip) var(--ease-out);
}
:where(.ds) .checkbox:checked, :where(.ds) .checkbox:indeterminate { background: var(--accent); box-shadow: none; }
:where(.ds) .checkbox:checked::after { transform: rotate(-45deg) scale(1); opacity: 1; }
:where(.ds) .checkbox:indeterminate::after { width: 8px; height: 0; margin-top: 0; border-left: 0; border-bottom: 2px solid var(--accent-fg); transform: none; opacity: 1; }

/* Card ← components-cards.css .cd-card */
:where(.ds) .card {
  position: relative;
  display: flex; flex-direction: column;
  padding: var(--space-2) var(--space-2) var(--space-3);
  border-radius: var(--radius-lg);
  background: var(--bg-1);
  box-shadow: var(--shadow-sm), inset 0 0 0 0.5px var(--border-default);
  cursor: pointer; min-width: 0;
  transition: transform var(--dur-flip) var(--ease-out);
}

/* Callout ← components-callout.css .co */
:where(.ds) .callout {
  display: flex; align-items: flex-start; gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  font-size: var(--type-sm); line-height: var(--lh-sm); color: var(--fg-1);
}

/* Dialog ← components-dialogs.css .dg-sheet (its absolute placement belongs to the specimen stage) */
:where(.ds) .dialog {
  display: flex; flex-direction: column; gap: var(--space-2);
  padding: var(--space-4);
  background: var(--bg-2);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg), inset 0 0 0 0.5px var(--x-island-edge);
  color: var(--fg-0);
}

/* Tooltip ← components-tooltips.css .tt-tip */
:where(.ds) .tooltip {
  position: relative;
  display: inline-flex; align-items: center; gap: var(--space-1);
  width: max-content; padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--fg-0); color: var(--bg-1);
  font-size: var(--type-xs); font-weight: var(--weight-medium); line-height: var(--lh-xs);
  box-shadow: var(--shadow-md);
}

/* Type roles (<Text role>) — token compositions from the schema registry; no new value. */
:where(.ds) .t-title { font-family: var(--font-display); font-size: var(--type-2xl); line-height: var(--lh-2xl); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-tight); }
:where(.ds) .t-heading { font-family: var(--font-display); font-size: var(--type-xl); line-height: var(--lh-xl); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-tight); }
:where(.ds) .t-subheading { font-family: var(--font-body); font-size: var(--type-lg); line-height: var(--lh-lg); font-weight: var(--weight-medium); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-body { font-family: var(--font-body); font-size: var(--type-base); line-height: var(--lh-base); font-weight: var(--weight-regular); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-body-sm { font-family: var(--font-body); font-size: var(--type-sm); line-height: var(--lh-sm); font-weight: var(--weight-regular); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-caption { font-family: var(--font-body); font-size: var(--type-xs); line-height: var(--lh-xs); font-weight: var(--weight-regular); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-label { font-family: var(--font-body); font-size: var(--type-sm); line-height: var(--lh-sm); font-weight: var(--weight-medium); letter-spacing: var(--tracking-normal); }
:where(.ds) .t-eyebrow { font-family: var(--font-body); font-size: var(--type-xs); line-height: var(--lh-xs); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-wide); }
:where(.ds) .t-code { font-family: var(--font-mono); font-size: var(--type-sm); line-height: var(--lh-sm); font-weight: var(--weight-regular); letter-spacing: 0; }
:where(.ds) .t-num { font-variant-numeric: tabular-nums; }

