{
  "$extensions": {
    "sh.maude": {
      "defaultTheme": "light",
      "rootClass": "maude-v2",
      "schemaVersion": 1,
      "source": "canvas",
      "system": "maude-v2",
      "themes": [
        "light",
        "dark"
      ]
    }
  },
  "$schema": "https://raw.githubusercontent.com/1aGh/maude/main/apps/studio/schema/ds-tokens-v1.schema.json",
  "alias": {
    "accent-muted": {
      "$extensions": {
