        "sh.maude": {
          "alias": true,
          "css": "--canvas-bg"
        }
      },
      "$value": "{x.canvas-bg}"
    },
    "canvas-dot": {
      "$extensions": {
        "sh.maude": {
          "alias": true,
          "css": "--canvas-dot"
        }
      },
